// 논산대건고등학교 (충남 논산시) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by daegeon-local-builder
// from an estimated manually traced aerial boundary + OSM building footprints + Copernicus GLO-30 DSM: every school building destructible (grammar models, floors estimated where OSM has none),
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, DAEGEON_PLACEMENTS, DAEGEON_BUILDING_BASE, DAEGEON_HEIGHT_GRIDS, DAEGEON_HEIGHT_RANGE_M, DAEGEON_ENV_IDS, DAEGEON_DISPLAY, DAEGEON_START_FRAME, DAEGEON_OVERVIEW_AZIMUTH, DAEGEON_CAMERA, DAEGEON_PROVENANCE } from './data.js';
import { DAEGEON_FOOTPRINTS } from './footprints.js';
import { DAEGEON_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(DAEGEON_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/daegeon/${file}`, import.meta.url).href;
const HAZE = DAEGEON_DISPLAY.haze, FADE = DAEGEON_DISPLAY.fade;

export const DAEGEON = Object.freeze({
  id: 'daegeon',
  meta: Object.freeze({ school: '논산대건고등학교', campus: '충남 논산시', short: '대건고', modelNoun: '대건고' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: DAEGEON_PLACEMENTS,
  approvedCount: DAEGEON_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: 'main',
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600 ? { min: [-19,-12,-39], max: [34,-1,-31], azimuth: 0, elevationDegrees: 10 } : { min: [-22,-2,-41], max: [26,10,-28], azimuth: 0 }; }, overviewAzimuth: DAEGEON_OVERVIEW_AZIMUTH }),
  camera: DAEGEON_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: DAEGEON_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: DAEGEON_HEIGHT_GRIDS, buildingBase: DAEGEON_BUILDING_BASE, exactHeightAt(e,n) { if(e > -17.125 && e < 53.5 && n > -70 && n < 51.325) return -1.2; if(e >= -19.125 && e <= 55.5 && n >= -72 && n <= 53.325) return 0; return null; }, source: DAEGEON_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: DAEGEON_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: DAEGEON_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'daegeon-local-builder baked ground' }),
  }),
  protected: Object.freeze({ models: DAEGEON_PROTECTED }),
  hazardTape: Object.freeze({ footprints: DAEGEON_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: DAEGEON_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default DAEGEON;
